const params = JSON.parse($input.first().json.query);
if (!params.user_id) return 'Error: missing user_id';
if (!params.title || params.hour === undefined || params.minute === undefined) return 'Error: missing title, hour, or minute';

const time_of_day = String(params.hour).padStart(2,'0') + ':' + String(params.minute).padStart(2,'0') + ':00';

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://jdfkndqfytvylbtyfivw.supabase.co/rest/v1/user_reminders',
    headers: {
      'apikey': $credentials.supabaseApi.apiKey,
      'Authorization': `Bearer ${$credentials.supabaseApi.apiKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: {
      user_id: params.user_id,
      title: params.title,
      subtitle: params.title,
      frequency: params.frequency || 'daily',
      time_of_day: time_of_day,
      weekday: params.weekday || null,
      enabled: true,
      icon_code_point: 0
    }
  });
  return `Success! Reminder added. ID: ${response[0]?.id}`;
} catch (error) {
  return `Database Error: ${error.message}`;
}

const params = JSON.parse($input.first().json.query);
if (!params.user_id) return 'Error: missing user_id';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://jdfkndqfytvylbtyfivw.supabase.co/rest/v1/user_reminders?select=id,title,time_of_day,frequency&user_id=eq.${params.user_id}`,
    headers: {
      'apikey': $credentials.supabaseApi.apiKey,
      'Authorization': `Bearer ${$credentials.supabaseApi.apiKey}`,
      'Content-Type': 'application/json'
    }
  });
  if (response.length === 0) return 'No reminders found for this user.';
  return `Found reminders: ${JSON.stringify(response)}`;
} catch (error) {
  return `Database Error: ${error.message}`;
}

const params = JSON.parse($input.first().json.query);
if (!params.user_id || !params.id) return 'Error: missing user_id or id';

let updateBody = {};
if (params.title) {
  updateBody.title = params.title;
  updateBody.subtitle = params.title;
}
if (params.hour !== undefined && params.minute !== undefined) {
  updateBody.time_of_day = String(params.hour).padStart(2,'0') + ':' + String(params.minute).padStart(2,'0') + ':00';
}
updateBody.updated_at = new Date().toISOString();

try {
  const response = await this.helpers.httpRequest({
    method: 'PATCH',
    url: `https://jdfkndqfytvylbtyfivw.supabase.co/rest/v1/user_reminders?id=eq.${params.id}&user_id=eq.${params.user_id}`,
    headers: {
      'apikey': $credentials.supabaseApi.apiKey,
      'Authorization': `Bearer ${$credentials.supabaseApi.apiKey}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: updateBody
  });
  if (response.length === 0) return 'Error: Reminder not found or not owned by user';
  return `Success! Reminder ID ${params.id} updated.`;
} catch (error) {
  return `Database Error: ${error.message}`;
}

